({params, imports}) => {
    const encounter = params.entity;
    const moment = imports.moment;
    const formElement = params.formElement;
    const _ = imports.lodash;
    let visibility = true;
    let value = null;
    let answersToSkip = [];
    let validationErrors = [];
    const CONCEPT_SCREENING_RELATIVES_UUID = "432a0a40-9aea-5640-8558-ca7764122eb4";
    const CONCEPT_SCREENING_RELATIONSHIP_UUID = "ef4b750e-b745-5769-af9b-8bb5e65fe4f7";
    let recordedRelationships = [];

    const allRelationships = ["93ec0704-c100-558f-96f6-a64c293a5ab2", "025e1514-00bb-58bb-bfe0-0c3ec556dfce", "f165a155-113b-5970-a316-57380d1c3fbe", "ffd95f25-32bc-5efa-9aed-39be569b8e1a", "c5e615ba-60a0-5421-82ca-4f0409f32da7", "e9633130-60b2-5b93-b17e-ee0ba5c2b105", "e84218bb-dbca-51fe-8600-0259c6d1929c", "1f02be71-8053-5133-ab29-f979aefbd390", "72970145-36c3-5970-a1f7-d749b1a4e771", "96ba0af3-6945-531a-ac64-ea4da5cf4b7e", "e402908d-e43c-4534-a6de-d1d40c05e749", "d4e3b5dc-f89d-5e86-97fc-b19419cfb974"];

    const screeningRelatives = encounter.individual.findLatestObservationFromEncounters(CONCEPT_SCREENING_RELATIVES_UUID, encounter);

    if (screeningRelatives) {
        screeningRelatives.getValue().forEach((row) => {
            const relationship = row.findObservationByConceptUUID(CONCEPT_SCREENING_RELATIONSHIP_UUID);
            if (relationship) {
                recordedRelationships.push(relationship.getValue());
            }
        });
    }

    _.forEach(_.difference(allRelationships, recordedRelationships), (answer) => {
        const answerToSkip = formElement.getAnswerWithConceptUuid(answer);
        if (answerToSkip) answersToSkip.push(answerToSkip);
    });

    return new imports.rulesConfig.FormElementStatus(formElement.uuid, visibility, value, answersToSkip, validationErrors);
};

